/**
 * Static files of every generated Playwright project. Kept as strings because they are written into
 * the project (and stored as editable AutomationScript rows), not compiled into the API.
 */

export const PLAYWRIGHT_CONFIG = `import { defineConfig, devices } from '@playwright/test';

// Generated by QA Pilot. Values come from the selected test environment at run time.
const browsers = (process.env.QAPILOT_BROWSERS ?? 'chromium').split(',').map((b) => b.trim()).filter(Boolean);
const [w, h] = (process.env.QAPILOT_VIEWPORT ?? '1366x768').split('x').map(Number);
const DEVICE: Record<string, string> = { chromium: 'Desktop Chrome', firefox: 'Desktop Firefox', webkit: 'Desktop Safari' };

export default defineConfig({
  testDir: './tests',
  outputDir: process.env.QAPILOT_OUTPUT ?? './test-results',
  timeout: Number(process.env.QAPILOT_TIMEOUT ?? 30000),
  fullyParallel: true,
  reporter: [[require.resolve('./support/qapilot-reporter.js')]],
  use: {
    baseURL: process.env.BASE_URL,
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    trace: 'retain-on-failure',
    actionTimeout: 10000,
  },
  projects: browsers.map((name) => ({ name, use: { ...devices[DEVICE[name] ?? 'Desktop Chrome'], viewport: { width: w || 1366, height: h || 768 } } })),
});
`;

export const REPORTER = `// Generated by QA Pilot: streams one JSON line per event so the server can show live progress.
const strip = (s) => String(s ?? '').replace(/\\u001b\\[[0-9;]*m/g, '');
const emit = (o) => process.stdout.write('@@QAPILOT@@' + JSON.stringify(o) + '\\n');
class QAPilotReporter {
  onBegin(config, suite) { emit({ type: 'begin', total: suite.allTests().length }); }
  onTestBegin(test, result) { emit({ type: 'testBegin', title: test.title, project: test.parent.project()?.name, retry: result.retry }); }
  onTestEnd(test, result) {
    emit({
      type: 'testEnd', title: test.title, project: test.parent.project()?.name, status: result.status, expectedStatus: test.expectedStatus,
      retry: result.retry, willRetry: result.status !== 'passed' && result.status !== 'skipped' && result.retry < test.retries,
      duration: result.duration, error: strip(result.error?.message).slice(0, 4000), errorStack: strip(result.error?.stack).slice(0, 4000),
      annotations: test.annotations, steps: result.steps.map((s) => ({ title: s.title, error: strip(s.error?.message).slice(0, 500) || undefined, duration: s.duration })),
      attachments: result.attachments.filter((a) => a.path || a.body).map((a) => ({ name: a.name, path: a.path, contentType: a.contentType, body: a.path ? undefined : a.body?.toString('base64') })),
    });
  }
  onError(error) { emit({ type: 'error', message: strip(error.message) }); }
  onEnd(result) { emit({ type: 'end', status: result.status }); }
  // Claim stdout so Playwright does not add its default (dot) reporter on top of ours.
  printsToStdio() { return true; }
}
module.exports = QAPilotReporter;
`;

export const FIXTURES = `import { test as base, expect, Locator } from '@playwright/test';

/**
 * Evidence fixture (auto): collects console and network logs; on failure attaches a full-page screenshot,
 * an annotated screenshot highlighting the element the test last interacted with, and both logs.
 * Playwright itself adds the failure screenshot, video and trace (see playwright.config.ts).
 */
export const test = base.extend<{ evidence: void }>({
  evidence: [async ({ page }, use, testInfo) => {
    const consoleLogs: unknown[] = [];
    const network: unknown[] = [];
    page.on('console', (m) => consoleLogs.push({ time: new Date().toISOString(), type: m.type(), text: m.text(), location: m.location() }));
    page.on('pageerror', (e) => consoleLogs.push({ time: new Date().toISOString(), type: 'pageerror', text: String(e) }));
    page.on('requestfinished', async (r) => {
      const res = await r.response().catch(() => null);
      network.push({ time: new Date().toISOString(), method: r.method(), url: r.url(), status: res?.status(), resourceType: r.resourceType(), timing: r.timing() });
    });
    page.on('requestfailed', (r) => network.push({ time: new Date().toISOString(), method: r.method(), url: r.url(), failure: r.failure()?.errorText }));
    await use();
    if (testInfo.status !== testInfo.expectedStatus && testInfo.status !== 'skipped') {
      await page.screenshot({ fullPage: true }).then((b) => testInfo.attach('full-page-screenshot', { body: b, contentType: 'image/png' })).catch(() => {});
      // Highlight the element under test; if the page moved on (e.g. a result page replaced the form),
      // highlight the outcome region instead so every failure has an annotated screenshot.
      const marked = (page as unknown as { __qaLast?: Locator }).__qaLast;
      let last: Locator | undefined = marked && (await marked.count().catch(() => 0)) > 0 ? marked : undefined;
      for (const sel of ['[aria-invalid=true]', '[role=alert]', '[role=status]', 'main']) {
        if (last) break;
        if ((await page.locator(sel).count().catch(() => 0)) > 0) last = page.locator(sel).first();
      }
      if (last) {
        await last.first().evaluate((el: HTMLElement) => {
          el.scrollIntoView({ block: 'center' });
          el.style.outline = '4px solid #dc2626';
          el.style.outlineOffset = '3px';
          el.style.boxShadow = '0 0 0 9999px rgba(15,23,42,0.25)';
        }, undefined, { timeout: 2000 }).then(() => page.screenshot()).then((b) => testInfo.attach('annotated-screenshot', { body: b, contentType: 'image/png' })).catch(() => {});
      }
      await testInfo.attach('console-log', { body: JSON.stringify(consoleLogs, null, 2), contentType: 'application/json' });
      await testInfo.attach('network-log', { body: JSON.stringify(network, null, 2), contentType: 'application/json' });
    }
  }, { auto: true }],
});
export { expect };
`;

export const DATA_HELPER = `import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/** Test Data Sheet exported by QA Pilot (data-driven tests). Values may carry a note: "4111111111111111 (Visa test card)". */
export interface DataRow { dataId: string; fieldName: string; dataType: string; valid: string[]; invalid: string[]; boundaries: Record<string, string> }
const rows: DataRow[] = JSON.parse(readFileSync(join(__dirname, '..', 'data', 'test-data.json'), 'utf8'));

/** Strip a trailing "(explanation)" from a test-data value. */
export const raw = (v: string) => v.replace(/\\s+\\([^)]*\\)\\s*$/, '');
/** Length annotated in a boundary value, e.g. "(7 chars)" → 7. */
export const annotatedLength = (v: string) => Number(/\\((\\d+) (?:chars?|digits?|characters?)\\)/.exec(v)?.[1] ?? NaN);

const words = (s: string) => s.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length >= 3);

export const data = {
  rows,
  item(dataId: string): DataRow {
    const r = rows.find((x) => x.dataId === dataId);
    if (!r) throw new Error(\`Test data \${dataId} not found in data/test-data.json\`);
    return r;
  },
  /** Best match for a form label ("Order amount (Rs.)" ↔ "Threshold amount"). */
  forLabel(label: string): DataRow | undefined {
    const l = label.toLowerCase();
    const usable = rows.filter((r) => r.dataType !== 'Account' && r.valid.length);
    return usable.find((r) => l.includes(r.fieldName.toLowerCase()) || r.fieldName.toLowerCase().includes(l))
      ?? usable.find((r) => words(r.fieldName).some((w) => words(label).includes(w)));
  },
  account(role: string) { return rows.find((r) => r.dataType === 'Account' && r.fieldName.toLowerCase().includes(role.toLowerCase())); },
};

/** Test credentials come from the encrypted environment settings, passed in by the runner - never stored in files. */
export function credentials(role?: string): { username: string; password: string } | undefined {
  const all = JSON.parse(process.env.QAPILOT_CREDENTIALS ?? '{}') as Record<string, { username: string; password: string }>;
  if (role && all[role]) return all[role];
  return Object.values(all)[0];
}
`;

export const APP_PAGE = `import { expect, Locator, Page } from '@playwright/test';
import { data, raw } from './data';

const esc = (s: string) => s.replace(/[.*+?^\${}()|[\\]\\\\]/g, '\\\\$&');
const SUBMIT = /^(submit|save|log ?in|sign ?in|create( account)?|register|pay( now)?|continue|next|send|confirm|place order)$/i;

/** Base Page Object: finds controls the way a user does (by visible label / role), so scripts survive markup changes. */
export class AppPage {
  constructor(readonly page: Page, readonly module: string, readonly defaultPath: string) {}

  get path(): string {
    const map = JSON.parse(process.env.QAPILOT_MODULE_PATHS ?? '{}') as Record<string, string>;
    return map[this.module] ?? this.defaultPath;
  }

  /** Remember the element under test for the annotated failure screenshot. */
  protected mark(l: Locator): Locator {
    (this.page as unknown as { __qaLast?: Locator }).__qaLast = l;
    return l;
  }

  async open() {
    const res = await this.page.goto(this.path);
    expect(res?.status() ?? 200, \`\${this.path} should load\`).toBeLessThan(500);
  }

  field(label: string): Locator {
    return this.page.getByLabel(new RegExp(esc(label), 'i')).first();
  }

  async requireField(label: string): Promise<Locator> {
    const f = this.mark(this.field(label));
    if ((await f.count()) === 0) throw new Error(\`Field "\${label}" was not found on \${this.path}. Update the Page Object or the module path for "\${this.module}".\`);
    return f;
  }

  async fill(label: string, value: string) {
    const f = await this.requireField(label);
    await f.fill(value);
  }

  /** Fill every other empty field of the form with a valid value from the Test Data Sheet. */
  async completeForm(skip: string[] = []) {
    const inputs = this.page.locator('form input:visible, form textarea:visible');
    for (let i = 0; i < (await inputs.count()); i++) {
      const el = inputs.nth(i);
      const type = (await el.getAttribute('type')) ?? 'text';
      if (['hidden', 'submit', 'button', 'checkbox', 'radio', 'file'].includes(type) || (await el.inputValue())) continue;
      const label = await el.evaluate((e: HTMLInputElement) => e.labels?.[0]?.textContent?.trim() ?? e.getAttribute('aria-label') ?? e.name ?? '');
      if (skip.some((s) => label.toLowerCase().includes(s.toLowerCase()))) continue;
      const row = data.forLabel(label);
      if (row) await el.fill(raw(row.valid[0]));
    }
  }

  async submit() {
    const named = this.page.getByRole('button', { name: SUBMIT });
    const btn = (await named.count()) ? named.first() : this.page.locator('form [type=submit]').first();
    await Promise.all([this.page.waitForLoadState('domcontentloaded'), btn.click()]);
  }

  async isInvalid(label: string): Promise<boolean> {
    const f = this.field(label);
    if ((await f.count()) === 0) return false;
    return f.evaluate((e: HTMLInputElement) => e.getAttribute('aria-invalid') === 'true' || (e.form?.dataset.submitted === '1' && !e.checkValidity()));
  }

  async expectFieldValid(label: string) {
    this.mark(this.field(label));
    expect(await this.isInvalid(label), \`"\${label}" should be accepted\`).toBe(false);
  }

  async expectFieldInvalid(label: string) {
    this.mark(this.field(label));
    expect(await this.isInvalid(label), \`"\${label}" should be rejected with a validation error\`).toBe(true);
  }

  async expectNoFieldErrors() {
    const invalid = await this.page.locator('[aria-invalid=true]').count();
    expect(invalid, 'no field should be flagged invalid').toBe(0);
  }

  /** Some error feedback is shown: an alert or a field marked invalid. */
  async expectSomeError() {
    const n = (await this.page.getByRole('alert').count()) + (await this.page.locator('[aria-invalid=true]').count());
    expect(n, 'an error message or invalid field should be shown').toBeGreaterThan(0);
  }

  async expectText(re: RegExp) { await expect(this.page.locator('body')).toContainText(re); }
  async expectNoText(re: RegExp) { await expect(this.page.locator('body')).not.toContainText(re); }

  /** Business rule outcome, e.g. "discount": applied when the keyword appears and is not negated ("No discount"). */
  async expectRuleApplied(keyword: string, applied: boolean) {
    const text = (await this.page.locator('main, body').first().innerText()).toLowerCase();
    const k = keyword.toLowerCase();
    const isApplied = text.includes(k) && !new RegExp(\`\\\\b(no|without|not eligible for)\\\\s+\${esc(k)}\`).test(text);
    expect(isApplied, applied ? \`"\${keyword}" should be applied\` : \`"\${keyword}" should NOT be applied\`).toBe(applied);
  }

  /** Log-in helper: finds the user name and password fields by label. */
  async loginWith(username: string, password: string) {
    const user = this.mark(this.page.getByLabel(/e-?mail|user ?name|login|user id/i).first());
    await user.fill(username);
    await this.page.getByLabel(/password/i).first().fill(password);
    await this.submit();
  }
}
`;

